<script setup lang="ts">
import { IonButton, IonPage } from '@ionic/vue'
import { App } from '@capacitor/app'
import { ref } from 'vue'
import ClearIcon from '@/components/svg/ClearIcon.vue'
import TransparentSvg from '@/assets/transparent.svg'

interface Props {
  src: string
  closable: boolean
}

interface Emits {
  (e: 'close'): void
  (e: 'play'): void
}
// props with default closable value
const props = defineProps<Props>()
defineEmits<Emits>()

const videoRef = ref<HTMLVideoElement | null>(null)

App.addListener('appStateChange', (state) => {
  if (state.isActive) {
    videoRef.value?.play()
  }
  else {
    videoRef.value?.pause()
  }
})
</script>

<template>
  <ion-page class="absolute top-0 left-0 z-202">
    <video
      ref="videoRef"
      autoplay
      :controls="false"
      :loop="false"
      class="w-full h-full bg-#000"
      :poster="TransparentSvg"
      @ended="$emit('close')"
      @play="$emit('play')"
    >
      <source :src="props.src" type="video/mp4">
    </video>
    <ion-button
      v-if="props.closable"
      class="absolute top-2 left-2"
      fill="clear"
      @click="() => $emit('close')"
    >
      <clear-icon />
    </ion-button>
  </ion-page>
</template>
